<?php require_once 'bootstrap.php';$u=require_login();$code=(string)($_GET['template']??$_POST['template']??'');$st=db()->prepare('SELECT * FROM document_templates WHERE code=?');$st->execute([$code]);$t=$st->fetch();if(!$t){http_response_code(404);exit('Template non trovato');}$done=null;if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$title=trim($_POST['title']??$t['title']);$body=trim($_POST['body']??'');$html='<article class="print-doc"><h1>'.h($title).'</h1><p><b>Data:</b> '.h($_POST['date']??date('Y-m-d')).'</p><div>'.nl2br(h($body)).'</div></article>';$sic=sic_id();$dir=__DIR__.'/storage/generated';if(!is_dir($dir))mkdir($dir,0770,true);$path=$dir.'/'.$sic.'.html';file_put_contents($path,'<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="../../assets/css/app.css">'.$html);$hash=hash_file('sha256',$path);db()->prepare('INSERT INTO generated_documents(sic_id,template_sic_id,owner_sic_id,title,payload_json,html_path,sha256) VALUES(?,?,?,?,?,?,?)')->execute([$sic,$t['sic_id'],$u['sic_id'],$title,json_encode($_POST,JSON_UNESCAPED_UNICODE),$path,$hash]);$done=$sic;}$pageTitle=$t['title'];require '_header.php';?><section class="card"><h1><?=h($t['title'])?></h1><?php if($done):?><div class="success">Documento generato: <?=h($done)?></div><a class="btn primary" href="document-print.php?id=<?=urlencode($done)?>" target="_blank">Apri / stampa PDF</a><?php else:?><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="template" value="<?=h($code)?>"><label>Titolo<input name="title" value="<?=h($t['title'])?>"></label><label>Data<input type="date" name="date" value="<?=date('Y-m-d')?>"></label><label>Contenuto<textarea name="body" rows="12"></textarea></label><button class="btn primary">Genera documento</button></form><?php endif;?></section><?php require '_footer.php';?>